package com.citacloud.springboot.contacloud.app.views;

import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.models.TipoAlmacen;
import com.citacloud.springboot.contacloud.app.security.TenantContext;
import com.citacloud.springboot.contacloud.app.services.*;
import com.citacloud.springboot.contacloud.app.views.components.*;
import com.vaadin.flow.component.*;
import com.vaadin.flow.component.checkbox.Checkbox;
import com.vaadin.flow.component.combobox.ComboBox;
import com.vaadin.flow.component.confirmdialog.ConfirmDialog;
import com.vaadin.flow.component.datepicker.DatePicker;
import com.vaadin.flow.component.dialog.Dialog;
import com.vaadin.flow.component.html.*;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.orderedlayout.*;
import com.vaadin.flow.component.select.Select;
import com.vaadin.flow.component.tabs.*;
import com.vaadin.flow.component.textfield.*;
import com.vaadin.flow.data.value.ValueChangeMode;
import com.vaadin.flow.router.*;
import jakarta.annotation.security.PermitAll;

import java.math.BigDecimal;
import java.text.DecimalFormat;
import java.time.format.DateTimeFormatter;
import java.util.*;

@Route(value="almacenes",layout=MainLayout.class)
@PageTitle("Almacenes | ContaCloud")
@PermitAll
public class AlmacenesView extends VerticalLayout implements BeforeEnterObserver {
    private static final DecimalFormat NUMBER=new DecimalFormat("#,##0.####");
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy");
    private final AlmacenService service;private final EmpresaModuloService modules;
    private final TextField search=new TextField("Buscar");private final ComboBox<AlmacenCatalogosDto.Opcion> branch=new ComboBox<>("Sucursal");
    private final Select<TipoAlmacen> type=new Select<>();private final Select<String> state=new Select<>();
    private final AppGrid<AlmacenDto> grid=new AppGrid<>(AlmacenDto.class);private final AppPagination pagination;
    private AlmacenCatalogosDto catalogs;

    public AlmacenesView(AlmacenService service,EmpresaModuloService modules){this.service=service;this.modules=modules;
        addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();
        Component create=can("almacenes.crear")?new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Nuevo almacén",e->form(null)):null;
        add(create==null?new AppPageHeader("ALMACENES","Administra los almacenes y consulta sus existencias y movimientos."):
            new AppPageHeader("ALMACENES","Administra los almacenes y consulta sus existencias y movimientos.",create));
        search.setPlaceholder("Nombre, código, sucursal o responsable...");search.setClearButtonVisible(true);search.setValueChangeMode(ValueChangeMode.LAZY);search.setValueChangeTimeout(400);
        branch.setClearButtonVisible(true);branch.setItemLabelGenerator(AlmacenCatalogosDto.Opcion::nombre);
        type.setLabel("Tipo");type.setItems(TipoAlmacen.values());type.setItemLabelGenerator(AlmacenesView::etiquetaTipo);type.setEmptySelectionAllowed(true);
        state.setLabel("Estado");state.setItems("Activos","Inactivos","Todos");state.setValue("Activos");
        search.addValueChangeListener(e->{if(e.isFromClient())reset();});branch.addValueChangeListener(e->{if(e.isFromClient())reset();});
        type.addValueChangeListener(e->{if(e.isFromClient())reset();});state.addValueChangeListener(e->{if(e.isFromClient())reset();});
        HorizontalLayout filters=new HorizontalLayout(search,branch,type,state);filters.addClassName("cc-filter-bar");filters.setAlignItems(Alignment.END);filters.setWidthFull();
        configureGrid();pagination=new AppPagination(r->load());add(filters,grid,pagination);
    }

    @Override public void beforeEnter(BeforeEnterEvent event){if(!modules.habilitado("INVENTARIO")||!can("almacenes.ver")){Notification.show("No tienes permiso para acceder a esta opción.");event.rerouteTo(DashboardView.class);return;}try{catalogs=service.catalogos();branch.setItems(catalogs.sucursales());load();}catch(RuntimeException ex){error(ex,"No fue posible cargar los almacenes.");}}
    private void configureGrid(){grid.addColumn(AlmacenDto::codigo).setHeader("Código").setAutoWidth(true);grid.addColumn(AlmacenDto::nombre).setHeader("Nombre").setFlexGrow(1);grid.addColumn(AlmacenDto::sucursal).setHeader("Sucursal").setFlexGrow(1);grid.addColumn(a->a.tipo().getEtiqueta()).setHeader("Tipo").setAutoWidth(true);grid.addColumn(a->display(a.responsable())).setHeader("Responsable").setFlexGrow(1);grid.addComponentColumn(a->badge(a.activo())).setHeader("Estado").setAutoWidth(true).setFlexGrow(0);grid.addComponentColumn(this::actions).setHeader("Acciones").setAutoWidth(true).setFlexGrow(0);grid.setEmptyStateText("No hay almacenes registrados.");}
    private Component actions(AlmacenDto a){HorizontalLayout row=new HorizontalLayout();row.addClassName("cc-grid-actions");row.setPadding(false);row.setSpacing(false);row.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver almacén",e->detail(a.id())));if(can("almacenes.editar"))row.add(new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar almacén",e->form(a.id())));return row;}
    private void load(){if(catalogs==null)return;grid.setEnabled(false);try{var r=pagination.currentRequest();var page=service.buscar(search.getValue(),id(branch),type.getValue(),stateFilter(),r.page(),r.size());grid.setItems(page.getContent());grid.setEmptyStateText(filtrado()?"No se encontraron almacenes con los filtros seleccionados.":"No hay almacenes registrados.");pagination.setTotal(page.getTotalElements());}catch(RuntimeException ex){error(ex,"No fue posible cargar los almacenes.");}finally{grid.setEnabled(true);}}
    private void reset(){pagination.reset();load();}private boolean filtrado(){return!search.getValue().isBlank()||branch.getValue()!=null||type.getValue()!=null||stateFilter()!=null;}private Boolean stateFilter(){return switch(state.getValue()==null?"Activos":state.getValue()){case"Activos"->true;case"Inactivos"->false;default->null;};}

    private void form(UUID id){try{AlmacenDto current=id==null?null:service.obtener(id);AlmacenCatalogosDto options=service.catalogos();Dialog d=dialog(current==null?"NUEVO ALMACÉN":"EDITAR ALMACÉN","820px");TextField name=new TextField("Nombre");name.setRequiredIndicatorVisible(true);name.setMaxLength(120);ComboBox<AlmacenCatalogosDto.Opcion> branchField=combo("Sucursal",options.sucursales());branchField.setRequiredIndicatorVisible(true);Select<TipoAlmacen> typeField=new Select<>();typeField.setLabel("Tipo");typeField.setItems(TipoAlmacen.values());typeField.setItemLabelGenerator(TipoAlmacen::getEtiqueta);typeField.setRequiredIndicatorVisible(true);typeField.setValue(TipoAlmacen.GENERAL);ComboBox<AlmacenCatalogosDto.Opcion> responsible=combo("Responsable (opcional)",options.responsables());responsible.setClearButtonVisible(true);TextArea address=new TextArea("Dirección / ubicación");address.setMaxLength(500);TextArea observation=new TextArea("Observación");observation.setMaxLength(1000);Checkbox defaultBranch=new Checkbox("Almacén predeterminado de la sucursal");if(current!=null){name.setValue(current.nombre());select(branchField,current.sucursalId());typeField.setValue(current.tipo());select(responsible,current.responsableId());address.setValue(value(current.direccion()));observation.setValue(value(current.observacion()));defaultBranch.setValue(current.predeterminadoSucursal());}d.add(section("INFORMACIÓN GENERAL",name,branchField,typeField,responsible,address,observation,defaultBranch));AppActionButton save=new AppActionButton(ActionType.SAVE,ButtonSize.MAIN,"Guardar",null);save.addClickListener(e->{save.setEnabled(false);try{AlmacenInput input=new AlmacenInput(name.getValue(),id(branchField),typeField.getValue(),id(responsible),address.getValue(),observation.getValue(),defaultBranch.getValue(),current==null?null:current.version());if(current==null)service.crear(input);else service.actualizar(current.id(),input);d.close();catalogs=service.catalogos();branch.setItems(catalogs.sucursales());load();Notification.show(current==null?"Almacén creado correctamente.":"Almacén actualizado correctamente.");}catch(RuntimeException ex){save.setEnabled(true);error(ex,"No fue posible guardar el almacén.");}});d.getFooter().add(save,new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}catch(RuntimeException ex){error(ex,"No fue posible abrir el almacén.");}}

    private void detail(UUID id){try{AlmacenDto a=service.obtener(id);Dialog d=dialog("ALMACÉN","min(1200px, 96vw)");Div heading=new Div(new H2(a.nombre()),badge(a.activo()));heading.addClassName("cc-detail-heading");d.add(heading,new AppDetailSection("INFORMACIÓN GENERAL").field("Código",a.codigo()).field("Sucursal",a.sucursal()).field("Tipo",a.tipo().getEtiqueta()).field("Responsable",display(a.responsable())).field("Dirección / ubicación",display(a.direccion())).field("Predeterminado",a.predeterminadoSucursal()?"Sí":"No").field("Productos con existencia",Long.toString(a.productosConExistencia())).field("Reservas activas","0"));Tabs tabs=new Tabs();Div content=new Div();content.setWidthFull();Tab stock=new Tab("EXISTENCIAS"),moves=new Tab("MOVIMIENTOS");if(can("almacenes.existencias"))tabs.add(stock);if(can("almacenes.movimientos"))tabs.add(moves);if(tabs.getComponentCount()>0){tabs.setWidthFull();tabs.addSelectedChangeListener(e->{content.removeAll();content.add(e.getSelectedTab()==stock?stockPanel(a):movementPanel(a));});d.add(tabs,content);content.add(tabs.getSelectedTab()==stock?stockPanel(a):movementPanel(a));}if(can("almacenes.editar"))d.getFooter().add(new AppActionButton(ActionType.EDIT,ButtonSize.MAIN,"Editar almacén",e->{d.close();form(a.id());}));if(a.activo()&&can("almacenes.desactivar"))d.getFooter().add(new AppActionButton(ActionType.DEACTIVATE,ButtonSize.MAIN,"Desactivar almacén",e->confirmState(a,d)));if(!a.activo()&&can("almacenes.activar"))d.getFooter().add(new AppActionButton(ActionType.ACTIVATE,ButtonSize.MAIN,"Activar almacén",e->confirmState(a,d)));d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}catch(RuntimeException ex){error(ex,"No fue posible consultar el almacén.");}}

    private Component stockPanel(AlmacenDto warehouse){VerticalLayout panel=new VerticalLayout();panel.setPadding(false);panel.setWidthFull();TextField q=new TextField("Buscar");q.setPlaceholder("Código o producto...");q.setClearButtonVisible(true);q.setValueChangeMode(ValueChangeMode.LAZY);ComboBox<AlmacenCatalogosDto.Opcion> category=combo("Categoría",service.categorias());category.setClearButtonVisible(true);Select<String> status=new Select<>();status.setLabel("Existencia");status.setItems("Todos","Con existencia","Sin existencia");status.setValue("Todos");HorizontalLayout filters=new HorizontalLayout(q,category,status);filters.addClassName("cc-filter-bar");filters.setWidthFull();AppGrid<ExistenciaAlmacenDto> table=new AppGrid<>(ExistenciaAlmacenDto.class);table.addColumn(ExistenciaAlmacenDto::codigo).setHeader("Código").setAutoWidth(true);table.addColumn(ExistenciaAlmacenDto::producto).setHeader("Producto").setFlexGrow(1);table.addColumn(ExistenciaAlmacenDto::categoria).setHeader("Categoría").setFlexGrow(1);table.addColumn(ExistenciaAlmacenDto::unidad).setHeader("Unidad").setAutoWidth(true);table.addColumn(x->number(x.existencia())).setHeader("Existencia").setAutoWidth(true);table.addColumn(x->number(x.reservado())).setHeader("Reservado").setAutoWidth(true);table.addColumn(x->x.disponible()==null?"No aplica":number(x.disponible())).setHeader("Disponible").setAutoWidth(true);table.setEmptyStateText("No hay productos para mostrar.");AppPagination[] pages=new AppPagination[1];Runnable load=()->{try{var r=pages[0].currentRequest();String s=switch(status.getValue()){case"Con existencia"->"CON_EXISTENCIA";case"Sin existencia"->"SIN_EXISTENCIA";default->"TODOS";};var page=service.existencias(warehouse.id(),q.getValue(),id(category),s,r.page(),r.size());table.setItems(page.getContent());pages[0].setTotal(page.getTotalElements());}catch(RuntimeException ex){error(ex,"No fue posible cargar las existencias.");}};pages[0]=new AppPagination(r->load.run());q.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});category.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});status.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});panel.add(filters,table,pages[0]);load.run();return panel;}

    private Component movementPanel(AlmacenDto warehouse){VerticalLayout panel=new VerticalLayout();panel.setPadding(false);panel.setWidthFull();TextField q=new TextField("Buscar");q.setPlaceholder("Producto o documento...");q.setClearButtonVisible(true);q.setValueChangeMode(ValueChangeMode.LAZY);Select<String> movementType=new Select<>();movementType.setLabel("Tipo");List<String> types=new ArrayList<>();types.add("Todos");types.addAll(service.tiposMovimiento(warehouse.id()));movementType.setItems(types);movementType.setValue("Todos");DatePicker from=date("Desde"),to=date("Hasta");HorizontalLayout filters=new HorizontalLayout(q,movementType,from,to);filters.addClassName("cc-filter-bar");filters.setWidthFull();AppGrid<MovimientoAlmacenDto> table=new AppGrid<>(MovimientoAlmacenDto.class);table.addColumn(x->DATE.format(x.fecha())).setHeader("Fecha").setAutoWidth(true);table.addColumn(MovimientoAlmacenDto::documento).setHeader("Documento").setFlexGrow(1);table.addColumn(MovimientoAlmacenDto::producto).setHeader("Producto").setFlexGrow(1);table.addColumn(MovimientoAlmacenDto::concepto).setHeader("Concepto").setFlexGrow(1);table.addColumn(x->number(x.entrada())).setHeader("Entrada").setAutoWidth(true);table.addColumn(x->number(x.salida())).setHeader("Salida").setAutoWidth(true);table.addColumn(x->number(x.saldoPosterior())).setHeader("Saldo posterior").setAutoWidth(true);table.setEmptyStateText("No hay movimientos para mostrar.");AppPagination[] pages=new AppPagination[1];Runnable load=()->{try{var r=pages[0].currentRequest();String selected="Todos".equals(movementType.getValue())?null:movementType.getValue();var page=service.movimientos(warehouse.id(),q.getValue(),selected,from.getValue(),to.getValue(),r.page(),r.size());table.setItems(page.getContent());pages[0].setTotal(page.getTotalElements());}catch(RuntimeException ex){error(ex,"No fue posible cargar los movimientos.");}};pages[0]=new AppPagination(r->load.run());q.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});movementType.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});from.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});to.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});panel.add(filters,table,pages[0]);load.run();return panel;}

    private void confirmState(AlmacenDto a,Dialog parent){boolean deactivate=a.activo();ConfirmDialog c=new ConfirmDialog();c.setHeader(deactivate?"Desactivar almacén":"Activar almacén");c.setText(deactivate?"El almacén dejará de estar disponible para nuevas operaciones. Solo puede desactivarse sin existencias ni documentos pendientes. ¿Deseas continuar?":"El almacén volverá a estar disponible para nuevas operaciones. ¿Deseas continuar?");c.setCancelable(true);c.setCancelText("Cancelar");c.setConfirmText(deactivate?"Desactivar":"Activar");if(deactivate)c.setConfirmButtonTheme("error primary");c.addConfirmListener(e->{try{if(deactivate)service.desactivar(a.id(),a.version());else service.activar(a.id(),a.version());parent.close();load();Notification.show(deactivate?"Almacén desactivado correctamente.":"Almacén activado correctamente.");}catch(RuntimeException ex){error(ex,"No fue posible cambiar el estado del almacén.");}});c.open();}

    private static Dialog dialog(String title,String width){Dialog d=new Dialog();d.setHeaderTitle(title);d.setWidth(width);return d;}private static Div section(String title,Component...fields){Div section=new Div();section.addClassName("cc-form-section");H3 h=new H3(title);h.addClassName("cc-section-heading");Div form=new Div(fields);form.addClassName("cc-dialog-form");section.add(h,form);return section;}private static <T extends AlmacenCatalogosDto.Opcion>ComboBox<T> combo(String label,List<T> items){ComboBox<T> c=new ComboBox<>(label);c.setItems(items);c.setItemLabelGenerator(AlmacenCatalogosDto.Opcion::nombre);return c;}private static UUID id(ComboBox<AlmacenCatalogosDto.Opcion> c){return c.getValue()==null?null:c.getValue().id();}private static void select(ComboBox<AlmacenCatalogosDto.Opcion> c,UUID id){if(id!=null)c.getListDataView().getItems().filter(x->id.equals(x.id())).findFirst().ifPresent(c::setValue);}private static DatePicker date(String label){DatePicker d=new DatePicker(label);d.setLocale(new Locale("es","DO"));d.setPlaceholder("DD/MM/YYYY");d.setClearButtonVisible(true);return d;}private static Span badge(boolean active){Span b=new Span(active?"Activo":"Inactivo");b.getElement().getThemeList().add("badge "+(active?"success":"contrast"));return b;}private static String display(String value){return value==null||value.isBlank()?"—":value;}private static String value(String value){return value==null?"":value;}private static String number(BigDecimal value){return value==null?"—":NUMBER.format(value);}static String etiquetaTipo(TipoAlmacen value){return value==null?"":value.getEtiqueta();}private static boolean can(String permission){return TenantContext.principalActual().permisos().contains(permission);}private static void error(RuntimeException ex,String fallback){String m=ex instanceof ReglaNegocioException||ex instanceof RecursoNoEncontradoException?ex.getMessage():fallback;Notification.show(m==null||m.isBlank()?fallback:m);}
}
